static void exit_nicely(PGconn *conn) {
    PQfinish(conn);
    exit(1);
}

static void show_binary_results(PGresult *res) {
    int i;
    int i_fnum, t_fnum;
    /* 使用 PQfnumber 来避免对结果中的字段顺序进行假设 */
    i_fnum = PQfnumber(res, "i");
    t_fnum = PQfnumber(res, "t");
    for (i = 0; i < PQntuples(res); i++) {
        char *iptr;
        char *tptr;
        int ival;
        /* 获取字段值（忽略可能为空的可能） */
        iptr = PQgetvalue(res, i, i_fnum);
        tptr = PQgetvalue(res, i, t_fnum);
        /* INT4 的二进制表现形式是网络字节序，建议转换成本地字节序。 */
        ival = ntohl(*(uint32_t *) iptr);
        /* TEXT 的二进制表现形式是文本，因此 libpq 能够给它附加一个字节零，把它看做 C 字符串。*/
        printf("tuple %d: got\n", i);
        printf("i = (%d bytes) %d\n", PQgetlength(res, i, i_fnum), ival);
        printf("t = (%d bytes) %s\n", PQgetlength(res, i, t_fnum), tptr);
        printf("\n\n");
    }
}

int main(int argc, char **argv) {
    const char conninfo[1024];
    PGconn *conn;
    PGresult *res;
    /* 此处user、passwd 等变量应从环境变量或配置文件读取，环境变量需用户自己按需配置；非环境变量情况下可直接赋值字符串 */
    char *passwd = getenv("EXAMPLE_PASSWD_ENV");
    char *port = getenv("EXAMPLE_PORT_ENV");
    char *hostaddr = getenv("EXAMPLE_HOST_ENV");
    char *username = getenv("EXAMPLE_USERNAME_ENV");
    char *dbname = getenv("EXAMPLE_DBNAME_ENV");

    /* 如果用户在命令行上提供了参数，那么使用该值为conninfo 字符串；否则使用环境变量或者缺省值。 */
    if (argc > 1)
        conninfo = argv[1];
    else
        sprintf(conninfo, "dbname=%s port=%s host=%s application_name=test connect_timeout=5 sslmode=allow user=%s password=%s",
                dbname, port, hostaddr, username, passwd);

    /* 和数据库建立连接 */
    conn = PQconnectdb(conninfo);
    /* 检查与服务器的连接是否成功建立 */
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        exit_nicely(conn);
    }

    /* 此处调用 PQexecParams 获取二进制结果后，解析并打印 */
    /* res = PQexecParams(...); */
    show_binary_results(res);

    PQclear(res);
    PQfinish(conn);
    return 0;
}
```

